"use client";
import { useEffect, useMemo, useState } from "react";

const D = Math.PI / 180;
// Coarse continent outlines (lat, lon). Land dots are generated by point-in-polygon tests.
const POLYS: number[][][] = [
  [[71,-156],[66,-168],[60,-165],[57,-158],[60,-148],[55,-132],[48,-124],[38,-123],[32,-117],[24,-110],[20,-105],[16,-95],[14,-92],[9,-84],[8,-78],[9,-76],[12,-83],[15,-88],[21,-87],[18,-94],[22,-98],[26,-97],[29,-94],[30,-88],[30,-84],[26,-82],[25,-80],[30,-81],[35,-76],[40,-74],[42,-70],[44,-66],[47,-61],[50,-60],[52,-56],[58,-62],[60,-64],[62,-72],[63,-78],[58,-78],[52,-79],[52,-88],[57,-92],[60,-94],[64,-90],[68,-95],[70,-110],[70,-125],[70,-140]],
  [[83,-35],[76,-70],[70,-52],[60,-44],[66,-36],[72,-22],[80,-18]],
  [[36,-6],[43,-9],[48,-5],[51,3],[54,9],[57,10],[60,5],[64,11],[70,20],[71,28],[69,33],[67,41],[68,60],[73,70],[76,100],[77,105],[72,130],[71,150],[69,170],[66,180],[60,163],[52,156],[54,142],[48,140],[43,132],[39,128],[35,129],[38,121],[40,122],[39,118],[37,122],[31,122],[25,119],[21,110],[21,106],[16,108],[10,106],[8,105],[2,104],[7,100],[13,98],[16,97],[20,93],[22,91],[21,87],[16,82],[13,80],[8,78],[8,77],[15,74],[21,72],[24,67],[25,62],[25,57],[22,59],[17,55],[13,45],[21,39],[28,34],[31,34],[36,36],[37,30],[36,27],[39,26],[41,22],[40,19],[45,13],[44,9],[43,5],[41,2],[37,-1]],
  [[36,-6],[36,10],[33,12],[31,20],[31,32],[22,37],[12,43],[11,51],[2,46],[-10,40],[-17,40],[-26,33],[-34,26],[-34,18],[-22,14],[-12,13],[-5,12],[4,9],[5,-2],[7,-12],[15,-17],[21,-17],[28,-11],[35,-6]],
  [[12,-72],[10,-62],[5,-52],[0,-50],[-7,-35],[-13,-38],[-23,-42],[-35,-57],[-41,-63],[-52,-68],[-55,-70],[-53,-74],[-42,-73],[-30,-71],[-18,-70],[-5,-81],[1,-80],[8,-77]],
  [[50,-5],[51,1],[55,-2],[58,-5],[55,-6],[53,-4]],
  [[-10,113],[-8,130],[-12,137],[-11,142],[-18,146],[-25,153],[-38,147],[-39,141],[-35,136],[-32,129],[-34,116],[-22,113],[-18,122],[-14,127]],
];

function inside(la: number, lo: number) {
  for (const p of POLYS) {
    let c = false;
    for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
      const [yi, xi] = p[i];
      const [yj, xj] = p[j];
      if (yi > la !== yj > la && lo < ((xj - xi) * (la - yi)) / (yj - yi) + xi) c = !c;
    }
    if (c) return true;
  }
  return false;
}

function landPoints() {
  const pts: [number, number][] = [];
  const step = 3.3;
  for (let la = -58; la <= 82; la += step) {
    const ls = step / Math.max(0.2, Math.cos(la * D));
    for (let lo = -180; lo < 180; lo += ls) if (inside(la, lo)) pts.push([la * D, lo * D]);
  }
  return pts;
}

const T = 15000; // full loop in ms
const f = (n: number) => n.toFixed(1);

function frame(el: number, pts: [number, number][]) {
  const H1 = 1.2, FL = 8, H2 = 1.8, RW = 4;
  const ease = (x: number) => (x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2);
  let u = 0, rw = 0;
  let phase: "hold1" | "fly" | "hold2" | "back" = "hold1";
  if (el < H1) { u = 0; phase = "hold1"; }
  else if (el < H1 + FL) { u = ease((el - H1) / FL); phase = "fly"; }
  else if (el < H1 + FL + H2) { u = 1; phase = "hold2"; }
  else { u = 1; phase = "back"; rw = ease((el - H1 - FL - H2) / RW); }

  const vec = (la: number, lo: number) => [Math.cos(la) * Math.cos(lo), Math.cos(la) * Math.sin(lo), Math.sin(la)];
  const A = vec(19.07 * D, 72.88 * D); // Mumbai
  const B = vec(34.05 * D, -118.24 * D); // Los Angeles
  const om = Math.acos(A[0] * B[0] + A[1] * B[1] + A[2] * B[2]);
  const ll = (s: number[]) => {
    const n = Math.hypot(s[0], s[1], s[2]);
    return [Math.asin(s[2] / n), Math.atan2(s[1], s[0])];
  };
  const gc = (uu: number) => {
    const k1 = Math.sin((1 - uu) * om) / Math.sin(om);
    const k2 = Math.sin(uu * om) / Math.sin(om);
    return [k1 * A[0] + k2 * B[0], k1 * A[1] + k2 * B[1], k1 * A[2] + k2 * B[2]];
  };
  // The camera follows the plane so it is always in view.
  const centerFor = (uu: number) => {
    const g = ll(gc(uu));
    return [Math.max(12 * D, Math.min(62 * D, g[0] * 0.8 + 8 * D)), g[1]];
  };
  let lat0: number, lon0: number;
  if (phase === "back") {
    const c1 = centerFor(1), c0 = centerFor(0);
    let dl = c0[1] - c1[1];
    dl = ((dl + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
    lat0 = c1[0] + (c0[0] - c1[0]) * rw;
    lon0 = c1[1] + dl * rw;
  } else {
    const c = centerFor(u);
    lat0 = c[0]; lon0 = c[1];
  }

  const CX = 250, CY = 250, R = 215;
  const sl0 = Math.sin(lat0), cl0 = Math.cos(lat0);
  const proj = (la: number, lo: number, r = 1) => {
    const dl = lo - lon0;
    const cla = Math.cos(la), sla = Math.sin(la);
    return { x: CX + R * r * cla * Math.sin(dl), y: CY - R * r * (cl0 * sla - sl0 * cla * Math.cos(dl)), c: r * (sl0 * sla + cl0 * cla * Math.cos(dl)) };
  };

  let near = "", mid = "", edge = "";
  for (const [la, lo] of pts) {
    const p = proj(la, lo);
    if (p.c <= 0.02) continue;
    const s = `M${f(p.x)} ${f(p.y)}h.01`;
    if (p.c > 0.5) near += s; else if (p.c > 0.22) mid += s; else edge += s;
  }
  let grat = "";
  const seg = (arr: number[][]) => {
    let open = false;
    for (const [la, lo] of arr) {
      const p = proj(la * D, lo * D);
      if (p.c > 0.01) { grat += `${open ? "L" : "M"}${f(p.x)} ${f(p.y)}`; open = true; } else open = false;
    }
  };
  for (let la = -60; la <= 60; la += 30) { const a: number[][] = []; for (let lo = -180; lo <= 180; lo += 10) a.push([la, lo]); seg(a); }
  for (let lo = -180; lo < 180; lo += 30) { const a: number[][] = []; for (let la = -90; la <= 90; la += 10) a.push([la, lo]); seg(a); }

  // great-circle arc lifted off the surface, the plane rides on it
  const at = (uu: number) => { const p = ll(gc(uu)); return proj(p[0], p[1], 1 + 0.2 * Math.sin(Math.PI * uu)); };
  const pathTo = (maxU: number, n: number) => {
    let d = "", open = false;
    for (let i = 0; i <= n; i++) {
      const p = at((i / n) * maxU);
      if (p.c > 0) { d += `${open ? "L" : "M"}${f(p.x)} ${f(p.y)}`; open = true; } else open = false;
    }
    return d;
  };
  const arc = pathTo(1, 56);
  const trail = u > 0 ? pathTo(u, Math.max(2, Math.round(56 * u))) : "";
  const pp = at(u), pq = at(Math.min(1, u + 0.012)), pb = at(Math.max(0, u - 0.012));
  const ang = (u < 0.999 ? Math.atan2(pq.x - pp.x, -(pq.y - pp.y)) : Math.atan2(pp.x - pb.x, -(pp.y - pb.y))) / D;
  const m = proj(19.07 * D, 72.88 * D), l = proj(34.05 * D, -118.24 * D);
  const planeOn = phase !== "back" || rw < 0.15;
  const prog = phase === "back" ? Math.max(0, 1 - rw * 2) : u;
  return {
    grat, near, mid, edge, arc, trail, prog,
    plane: `translate(${f(pp.x)} ${f(pp.y)}) rotate(${f(ang)})`,
    planeOp: pp.c > 0 && planeOn ? 1 : 0,
    mum: `translate(${f(m.x)} ${f(m.y)})`, mumOp: m.c > 0.05 ? 1 : 0,
    la: `translate(${f(l.x)} ${f(l.y)})`, laOp: l.c > 0.05 ? 1 : 0,
  };
}

const PLANE = "M0 -13 C1.6 -13 2.4 -11 2.4 -8 L2.6 -4 L13 2 L13 4.6 L2.6 1.6 L2.2 8 L5.6 10.4 L5.6 12.4 L0 11 L-5.6 12.4 L-5.6 10.4 L-2.2 8 L-2.6 1.6 L-13 4.6 L-13 2 L-2.6 -4 L-2.4 -8 C-2.4 -11 -1.6 -13 0 -13Z";

export default function Globe() {
  const pts = useMemo(landPoints, []);
  const [el, setEl] = useState(0); // starts at 0 so server and client render the same first frame

  useEffect(() => {
    const t0 = Date.now();
    const id = setInterval(() => setEl(((Date.now() - t0) % T) / 1000), 45);
    return () => clearInterval(id);
  }, []);

  const v = frame(el, pts);
  const mono = "var(--font-mono), monospace";

  return (
    <div className="mono" style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 18, width: "100%", maxWidth: 540 }}>
      <svg viewBox="0 0 500 500" width="100%" style={{ display: "block" }} role="img" aria-label="A 3D globe that follows a plane flying from Mumbai, India to Los Angeles, USA">
        <defs>
          <radialGradient id="gl-sphere" cx=".36" cy=".3" r=".9"><stop offset="0" stopColor="#1b2766" /><stop offset=".55" stopColor="#0a0f33" /><stop offset="1" stopColor="#040618" /></radialGradient>
          <radialGradient id="gl-halo" cx=".5" cy=".5" r=".5"><stop offset=".84" stopColor="#6c7bff" stopOpacity=".32" /><stop offset="1" stopColor="#6c7bff" stopOpacity="0" /></radialGradient>
          <radialGradient id="gl-shade" cx=".34" cy=".3" r=".8"><stop offset=".55" stopColor="#000" stopOpacity="0" /><stop offset="1" stopColor="#000" stopOpacity=".55" /></radialGradient>
          <radialGradient id="gl-pglow" cx=".5" cy=".5" r=".5"><stop offset="0" stopColor="#ffffff" stopOpacity=".55" /><stop offset="1" stopColor="#6ee7b7" stopOpacity="0" /></radialGradient>
        </defs>
        <circle cx="250" cy="250" r="246" fill="url(#gl-halo)" />
        <circle cx="250" cy="250" r="215" fill="url(#gl-sphere)" />
        <path d={v.grat} fill="none" stroke="#4455b8" strokeWidth=".8" strokeOpacity=".45" />
        <path d={v.edge} fill="none" stroke="#8ea0ff" strokeWidth="2.4" strokeLinecap="round" strokeOpacity=".28" />
        <path d={v.mid} fill="none" stroke="#9fb0ff" strokeWidth="2.6" strokeLinecap="round" strokeOpacity=".6" />
        <path d={v.near} fill="none" stroke="#b9c5ff" strokeWidth="2.8" strokeLinecap="round" strokeOpacity=".95" />
        <circle cx="250" cy="250" r="215" fill="url(#gl-shade)" />
        <circle cx="250" cy="250" r="215" fill="none" stroke="#6c7bff" strokeOpacity=".5" strokeWidth="1.4" />

        <path d={v.arc} fill="none" stroke="#f5b97a" strokeOpacity=".55" strokeWidth="1.8" strokeLinecap="round" strokeDasharray="3 7" />
        <path d={v.trail} fill="none" stroke="#6ee7b7" strokeWidth="3" strokeLinecap="round" />

        <g transform={v.mum} opacity={v.mumOp}>
          <circle r="12" fill="#f5b97a" fillOpacity=".3"><animate attributeName="r" values="5;18;5" dur="2.4s" repeatCount="indefinite" /><animate attributeName="fill-opacity" values=".5;0;.5" dur="2.4s" repeatCount="indefinite" /></circle>
          <circle r="5" fill="#f5b97a" stroke="#fff" strokeWidth="1.5" />
          <text x="11" y="-9" fontFamily={mono} fontSize="13" fontWeight="500" fill="#f8dfc0">Mumbai</text>
        </g>
        <g transform={v.la} opacity={v.laOp}>
          <circle r="12" fill="#6ee7b7" fillOpacity=".3"><animate attributeName="r" values="5;18;5" dur="2.4s" begin="1.2s" repeatCount="indefinite" /><animate attributeName="fill-opacity" values=".5;0;.5" dur="2.4s" begin="1.2s" repeatCount="indefinite" /></circle>
          <circle r="5" fill="#6ee7b7" stroke="#fff" strokeWidth="1.5" />
          <text x="11" y="-9" fontFamily={mono} fontSize="13" fontWeight="500" fill="#c8f6e6">Los Angeles</text>
        </g>

        <g transform={v.plane} opacity={v.planeOp}>
          <circle r="26" fill="url(#gl-pglow)" />
          <path d={PLANE} fill="#ffffff" stroke="#0a0f33" strokeWidth="1" transform="scale(1.15)" />
        </g>
      </svg>

      {/* route strip */}
      <div style={{ width: "100%", border: "1px solid #26262e", background: "rgba(12,13,18,0.85)", borderRadius: 18, padding: "16px 18px", display: "flex", alignItems: "center", gap: 14 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          <span style={{ fontSize: 11, letterSpacing: "0.12em", color: "var(--amber)" }}>FROM</span>
          <span style={{ fontSize: 16, fontWeight: 600, fontFamily: "var(--font-inter), sans-serif" }}>Mumbai</span>
          <span style={{ fontSize: 12, color: "#8f8f8f" }}>India</span>
        </div>
        <div aria-hidden="true" style={{ flex: "1 1 0", minWidth: 40, position: "relative", height: 36 }}>
          <div style={{ position: "absolute", left: 0, right: 0, top: 17, borderTop: "2px dashed #3a3f55" }} />
          <div style={{ position: "absolute", left: 0, top: 16, height: 4, borderRadius: 2, background: "linear-gradient(90deg,#f5b97a,#6ee7b7)", width: `${(v.prog * 100).toFixed(1)}%` }} />
          <div style={{ position: "absolute", top: 4, marginLeft: -14, left: `${(v.prog * 100).toFixed(1)}%` }}>
            <svg width="28" height="28" viewBox="-14 -14 28 28" style={{ transform: "rotate(90deg)", display: "block" }}><path d={PLANE} fill="#fff" /></svg>
          </div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 2, textAlign: "right" }}>
          <span style={{ fontSize: 11, letterSpacing: "0.12em", color: "var(--mint)" }}>TO</span>
          <span style={{ fontSize: 16, fontWeight: 600, fontFamily: "var(--font-inter), sans-serif" }}>Los Angeles</span>
          <span style={{ fontSize: 12, color: "#8f8f8f" }}>USA</span>
        </div>
      </div>
    </div>
  );
}
